INSERT INTO "code_sessions_runs" VALUES('run-paused-approval','!room:example.org:$conversation','agent','code',NULL,NULL,'@alice:example.org',NULL,'PAUSED',8,'{"run_id": "run-paused-approval", "agent_id": "code", "agent_name": "Code", "session_id": "!room:example.org:$conversation", "user_id": "@alice:example.org", "content": "I need approval first.", "content_type": "str", "model": "code-model", "model_provider": "Synthetic", "session_state": {"current_user_id": "@alice:example.org", "current_session_id": "!room:example.org:$conversation", "current_run_id": "run-paused-approval"}, "created_at": 1800000420, "status": "PAUSED", "metrics": {"input_tokens": 240, "output_tokens": 7, "total_tokens": 247, "time_to_first_token": 0.25, "duration": 0.5, "details": {"model": [{"input_tokens": 240, "output_tokens": 7, "total_tokens": 247, "id": "code-model", "provider": "Synthetic"}]}}, "messages": [{"id": "00000000-0000-4000-8000-00000000001b", "content": "<your_role>\n## Your Identity\nYou are Code (Matrix ID: @mindroom_code:mindroom.chat), a specialized agent in the Mindroom multi-agent system in a Matrix chatroom (with Markdown support).\nYou are powered by the Synthetic model: code-model.\nWhen working in teams with other agents, you should identify yourself as Code and leverage your specific expertise.\n\nIn Matrix chat contexts, conversation history from other Matrix senders may be provided inside a `<conversation>` block, with messages wrapped as `<msg from=\"@user:server\" display_name=\"Current Name\"><![CDATA[body]]></msg>`. The `from` attribute is the sender''s full Matrix ID and their stable identity. The optional `display_name` attribute is the sender''s current display name; it can change, so messages sharing a `from` value are from the same person even when their display names differ, and the newest display name is the current one. The CDATA body preserves code snippets, markdown, and other special characters exactly as written. A `<msg>` tag may also carry a `ts` attribute with the message''s local send time formatted as `YYYY-MM-DD HH:MM TZ` (e.g. `ts=\"2026-03-20 08:15 PDT\"`) and an `event_id` attribute for Matrix reactions and edits through `matrix_message.event_id`. Your prior replies remain ordinary assistant messages. The current message you are responding to may also be wrapped in the same `<msg from=\"...\" display_name=\"...\" ts=\"...\">` tag. When the user sent several messages together they are grouped inside a `<messages>` container (sent in quick succession) or a `<queued_messages>` container (arrived while you were still responding); treat such a group as one turn and respond once.\nWhen mentioning a user in your reply, always write the complete Matrix ID including the homeserver (e.g. `@alice:example.org`), never just the localpart before the colon. The chat client renders the full ID as a clickable mention pill.\n\n## Matrix Reply Targeting\nMindRoom dispatches responder turns before you see a message. In one-on-one or single-responder conversations, you may be selected automatically. In multi-agent, multi-team, or multi-human rooms and threads, users must use an explicit Matrix mention of the target responder for that responder to be selected. A natural-language addressing style, such as using an agent or team display name in plain text, is not a Matrix mention.\nIf a user later asks why you did not answer an earlier message, explain that you were not dispatched for that message unless you were explicitly mentioned, routed by the router, or selected as the only eligible responder. Do not apologize as if you saw the message and chose not to reply.\nMultiple explicitly mentioned agents can form an ad-hoc collaboration. Configured teams are targeted directly as their team workflow, not as members of an ad-hoc team.\n\n\n\n## Tool Execution Environment\n- All available tools run in the primary MindRoom runtime: `calculator`, `attachments`, `delegate`, `invite_router`.\n- No tools use a worker runtime.\n- File access for path tools: `workspace` (agent workspace and attachments only).Writes and checks code.\n</your_role>\n\n- To save a tool''s full supported output to a file in your workspace instead of returning it, pass `mindroom_output_path: <relative-path>` and then inspect the saved file with file, coding, python, or shell tools. In shell tools, `$MINDROOM_AGENT_WORKSPACE` points at that workspace; in worker-routed shell and python tools, `~` and `$HOME` point there too.\n\nIf you have file or shell tools, you can create new skills for yourself by writing files inside your own workspace; you never need write access to a global skills directory.\nA skill is a folder `skills/<skill-name>/` in your workspace containing a `SKILL.md` file, plus optional `scripts/` and `references/` subfolders.\n`SKILL.md` starts with YAML frontmatter declaring `name` and `description`, followed by the markdown instructions:\n\n---\nname: my-skill\ndescription: One-line summary of when to use this skill\n---\n\n# My Skill\nStep-by-step instructions...\n\nDo not write to the bundled, plugin, or user skill directories (for example `~/.mindroom/skills`); they may be read-only, and workspace skills take precedence over them anyway.\nA workspace skill you create or edit becomes available on your next run, without any config change.\nget_skill_script only reads skill scripts; run a script with your shell tools if you have them.\n\n\nWhen you need the user to choose between options, create an interactive question by including this JSON in your response with the following format:\n\nIMPORTANT: This is just an example. You can customize the question and options as needed.\n\n```interactive\n{\n    \"question\": \"How would you like me to proceed?\",\n    \"options\": [\n        {\"emoji\": \"\ud83d\ude80\", \"label\": \"Fast and automated\", \"value\": \"fast\"},\n        {\"emoji\": \"\ud83d\udc22\", \"label\": \"Careful and manual\", \"value\": \"slow\"}\n    ]\n}\n```\n\nIMPORTANT:\n- You must write ```interactive on the SAME LINE (no space or newline between the backticks and the word \"interactive\").\n- The JSON block will be automatically replaced with a formatted question showing the options with emojis.\n- Don''t write things like \"here are the options:\" before the JSON block - the formatted question will appear instead.\n- Write your response as if the formatted question will be shown directly to the user.\n- Only a SINGLE JSON block will be converted to an interactive question. DO NOT INCLUDE MULTIPLE BLOCKS!\n\nThe JSON block above will be automatically converted to this formatted display:\n\nHow would you like me to proceed?\n\n1. \ud83d\ude80 Fast and automated\n2. \ud83d\udc22 Careful and manual\n\nReact with an emoji or type the number to respond.\n\nThe user can respond by:\n- Clicking the emoji reaction\n- Typing the number (1, 2, etc.)\n\nKeep it simple: max 5 options with clear, concise labels.\n\n\n<additional_information>\n- Use markdown to format your answers.\n</additional_information>\n\n<mindroom_session_context>\n## Current Date and Time\nToday is Friday, January 15, 2027.\nTimezone: UTC (UTC)\n\n\n</mindroom_session_context>", "from_history": false, "stop_after_tool_call": false, "role": "system", "created_at": 1800000420}, {"id": "00000000-0000-4000-8000-00000000001c", "content": "Current message:\n<msg event_id=\"$run-paused-approval\" from=\"@alice:example.org\"><![CDATA[Multiply 6 by 7.]]></msg>", "from_history": false, "stop_after_tool_call": false, "role": "user", "created_at": 1800000420}, {"id": "00000000-0000-4000-8000-00000000001d", "content": "I need approval first.", "from_history": false, "stop_after_tool_call": false, "role": "assistant", "tool_calls": [{"id": "call-multiply", "type": "function", "function": {"name": "multiply", "arguments": "{\"a\": 6, \"b\": 7}"}}], "provider_data": {"mindroom_model": {"id": "code-model", "provider": "Synthetic"}}, "metrics": {"input_tokens": 240, "output_tokens": 7, "total_tokens": 247, "time_to_first_token": 0.25}, "created_at": 1800000420}], "metadata": {"io.mindroom.ai_run": {"version": 1, "prepared_context": {"tokens": 9785}, "compaction": {"decision": "none", "outcome": "none", "reason": "under_trigger", "current_history_tokens": 5482, "trigger_budget_tokens": 155697, "hard_budget_tokens": 179313, "fitted_replay_tokens": 5482, "replay_plan": {"mode": "configured", "estimated_tokens": 5482}}}, "room_id": "!room:example.org", "thread_id": "$conversation", "reply_to_event_id": "$run-paused-approval", "requester_id": "@alice:example.org", "correlation_id": "corr-run-paused-approval", "model_params": {"supports_native_structured_outputs": false, "supports_json_schema_outputs": false, "tool_message_role": "tool", "assistant_message_role": "assistant", "cache_response": false, "retries": 0, "delay_between_retries": 1, "exponential_backoff": false, "retry_with_guidance": true, "retry_with_guidance_limit": 1, "seed": 1, "min_response_chars": 320, "max_response_chars": 960, "chunk_chars": 40, "chars_per_second": 80.0, "tool_call_probability": 0.2}, "matrix_event_id": "$run-paused-approval", "matrix_seen_event_ids": ["$run-paused-approval"]}, "tools": [{"tool_call_id": "call-multiply", "tool_name": "multiply", "tool_args": {"a": 6, "b": 7}, "tool_call_error": null, "result": null, "metrics": null, "child_run_id": null, "stop_after_tool_call": false, "created_at": 1800000420, "requires_confirmation": true, "confirmed": null, "confirmation_note": null, "requires_user_input": null, "user_input_schema": null, "user_feedback_schema": null, "answered": null, "external_execution_required": null, "external_execution_silent": null, "approval_type": "mindroom_policy", "approval_id": null}], "requirements": [{"id": "00000000-0000-4000-8000-00000000001e", "created_at": "2027-01-15T08:07:00+00:00", "tool_execution": {"tool_call_id": "call-multiply", "tool_name": "multiply", "tool_args": {"a": 6, "b": 7}, "tool_call_error": null, "result": null, "metrics": null, "child_run_id": null, "stop_after_tool_call": false, "created_at": 1800000420, "requires_confirmation": true, "confirmed": null, "confirmation_note": null, "requires_user_input": null, "user_input_schema": null, "user_feedback_schema": null, "answered": null, "external_execution_required": null, "external_execution_silent": null, "approval_type": "mindroom_policy", "approval_id": null}}], "input": {"input_content": [{"id": "00000000-0000-4000-8000-00000000001c", "content": "Current message:\n<msg event_id=\"$run-paused-approval\" from=\"@alice:example.org\"><![CDATA[Multiply 6 by 7.]]></msg>", "from_history": false, "stop_after_tool_call": false, "role": "user", "created_at": 1800000420}]}}',1800000420,1800000420);
